-- ============================================================================
-- 019 — Compliance register: legislation, obligations, instruments and gazette
-- notifications. Generated by scripts/generate-compliance-seed.py.
--
-- Real Indian labour legislation with the applicability thresholds our audits
-- use. Idempotent by design: every statement is guarded with
-- `WHERE NOT EXISTS (natural key)`, so re-running `npm run db:seed` never
-- duplicates a register entry and never overwrites an administrator's edit.
-- ============================================================================


-- ─────────────────────────────── acts ───────────────────────────────

INSERT INTO compliance_acts (act_name, short_name, act_number, act_year, jurisdiction, state_name, ministry, department, enactment_date, effective_date, applicability_criteria, industry_applicability, employee_threshold, summary, official_source_url, status)
  SELECT 'Factories Act, 1948', 'Factories Act', '63 of 1948', 1948, 'Central', NULL, 'Ministry of Labour and Employment', 'Directorate General Factory Advice Service & Labour Institutes', '1948-09-23', '1949-04-01', 'Applies to every premises where a manufacturing process is carried on with ten or more workers with the aid of power, or twenty or more workers without the aid of power. Approval of building plans, registration and a licence under the state Factory Rules are mandatory before the premises is occupied or the process is started.', 'Manufacturing, processing, packing, repairing, printing, tailoring', '10 or more with power · 20 or more without power', 'The principal law on occupational safety, health and welfare in factories: approval of building plans, licensing and registration, working hours and holidays, welfare amenities such as drinking water, canteens and creches, safety of machinery and hazardous processes, the safety committee and safety officer requirements, and the reporting of accidents, dangerous occurrences and occupational diseases.', 'https://labour.gov.in/acts/factories-act-1948', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_acts WHERE act_name = 'Factories Act, 1948');

INSERT INTO compliance_acts (act_name, short_name, act_number, act_year, jurisdiction, state_name, ministry, department, enactment_date, effective_date, applicability_criteria, industry_applicability, employee_threshold, summary, official_source_url, status)
  SELECT 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952', 'EPF Act', '19 of 1952', 1952, 'Central', NULL, 'Ministry of Labour and Employment', 'Employees'' Provident Fund Organisation', '1952-03-04', '1952-11-01', 'Applies to every establishment in which twenty or more persons are employed, and to any establishment covered by a notification irrespective of headcount. Once covered, the establishment remains covered even if employment later falls below the threshold. International workers are covered from the first day of employment.', 'All industries other than those exempted by notification (e.g. certain co-operative societies)', '20 or more', 'Provides compulsory provident fund, pension (EPS) and deposit-linked insurance (EDLI). The employer must register the establishment, enrol every eligible employee within one month of joining, remit monthly contributions by the 15th of the following month, and file the monthly electronic challan-cum-return (ECR).', 'https://www.epfindia.gov.in/site_docs/PDFs/Downloads_PDFs/EPFAct1952.pdf', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_acts WHERE act_name = 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952');

INSERT INTO compliance_acts (act_name, short_name, act_number, act_year, jurisdiction, state_name, ministry, department, enactment_date, effective_date, applicability_criteria, industry_applicability, employee_threshold, summary, official_source_url, status)
  SELECT 'Employees'' State Insurance Act, 1948', 'ESI Act', '34 of 1948', 1948, 'Central', NULL, 'Ministry of Labour and Employment', 'Employees’ State Insurance Corporation', '1948-04-19', '1952-02-24', 'Applies to every factory using power in which ten or more persons are employed, and to every other establishment in which twenty or more persons are employed, in implemented areas — and to any establishment whose monthly wage bill makes it liable. Coverage extends to employees drawing wages up to the ceiling notified by the Central Government.', 'Factories, shops, hotels and restaurants, road transport, cinemas, medical and educational institutions', '10 (factory, with power) · 20 (other establishments)', 'Provides sickness, maternity, disablement and dependants'' benefits, medical benefit and funeral expenses to insured persons and their families. The employer must obtain the 17-digit employer code, register employees within ten days of joining, pay contributions monthly and file the return of contributions.', 'https://www.esic.gov.in/', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_acts WHERE act_name = 'Employees'' State Insurance Act, 1948');

INSERT INTO compliance_acts (act_name, short_name, act_number, act_year, jurisdiction, state_name, ministry, department, enactment_date, effective_date, applicability_criteria, industry_applicability, employee_threshold, summary, official_source_url, status)
  SELECT 'Contract Labour (Regulation and Abolition) Act, 1970', 'Contract Labour Act', '37 of 1970', 1970, 'Central', NULL, 'Ministry of Labour and Employment', 'Office of the Chief Labour Commissioner (Central)', '1970-09-05', '1971-02-10', 'Applies to every establishment in which twenty or more workmen are employed or were employed on any day of the preceding twelve months as contract labour, and to every contractor who employs or employed twenty or more workmen. A state notification may extend it below the threshold for particular works.', 'Manufacturing, construction, mines, plantations, and establishments using contract labour', '20 or more contract workmen', 'Regulates the employment of contract labour. The principal employer must register the establishment, engage only licensed contractors, maintain registers of workmen and wages, provide canteen, rest rooms, drinking water and first-aid facilities, and pay wages where the contractor fails to. The Act also empowers prohibition of contract labour in specified processes.', 'https://labour.gov.in/acts/contract-labour-regulation-and-abolition-act-1970', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_acts WHERE act_name = 'Contract Labour (Regulation and Abolition) Act, 1970');

INSERT INTO compliance_acts (act_name, short_name, act_number, act_year, jurisdiction, state_name, ministry, department, enactment_date, effective_date, applicability_criteria, industry_applicability, employee_threshold, summary, official_source_url, status)
  SELECT 'Payment of Gratuity Act, 1972', 'Gratuity Act', '39 of 1972', 1972, 'Central', NULL, 'Ministry of Labour and Employment', 'Office of the Labour Commissioner', '1972-08-21', '1972-09-16', 'Applies to every factory, mine, oilfield, plantation, port, railway company, shop or other establishment in which ten or more persons are employed or were employed on any day of the preceding twelve months. Coverage continues even if the number of employees falls below ten.', 'All establishments with ten or more employees', '10 or more', 'Gratuity is payable on resignation, retirement, superannuation, disablement or death after five years of continuous service: fifteen days'' wages for each completed year of service, computed on the last drawn basic pay plus dearness allowance, subject to the ceiling notified by the Central Government. It must be determined and paid within thirty days of falling due, and the employer must display the abstract of the Act.', 'https://labour.gov.in/acts/payment-gratuity-act-1972', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_acts WHERE act_name = 'Payment of Gratuity Act, 1972');

INSERT INTO compliance_acts (act_name, short_name, act_number, act_year, jurisdiction, state_name, ministry, department, enactment_date, effective_date, applicability_criteria, industry_applicability, employee_threshold, summary, official_source_url, status)
  SELECT 'Maternity Benefit Act, 1961', 'Maternity Benefit Act', '53 of 1961', 1961, 'Central', NULL, 'Ministry of Labour and Employment', 'Office of the Labour Commissioner', '1961-12-12', '1961-12-12', 'Applies to every establishment covered by the Factories Act, Mines Act and Plantations Labour Act and, after the 2017 amendment, to every establishment with ten or more employees, including shops and establishments.', 'All establishments with ten or more employees', '10 or more', 'Provides twenty-six weeks'' paid maternity leave for the first two children and twelve weeks for the third onwards, prenatal and postnatal care, medical bonus, nursing breaks, and — for establishments with fifty or more employees — a crèche facility. The 2017 amendment also introduced work-from-home where the nature of work permits.', 'https://labour.gov.in/acts/maternity-benefit-act-1961', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_acts WHERE act_name = 'Maternity Benefit Act, 1961');

INSERT INTO compliance_acts (act_name, short_name, act_number, act_year, jurisdiction, state_name, ministry, department, enactment_date, effective_date, applicability_criteria, industry_applicability, employee_threshold, summary, official_source_url, status)
  SELECT 'Tamil Nadu Shops and Establishments Act, 1947', 'TN Shops & Establishments', '36 of 1947', 1947, 'State', 'Tamil Nadu', 'Labour and Employment Department, Government of Tamil Nadu', 'Commissioner of Labour', '1947-12-31', '1948-01-01', 'Applies to every shop, commercial establishment, hotel, restaurant, theatre and place of public amusement in Tamil Nadu irrespective of headcount, with limited exemptions for establishments run by the owner''s family and for categories notified by the Government.', 'Shops, offices, commercial establishments, hotels and restaurants in Tamil Nadu', 'All sizes (state act)', 'Regulates opening and closing hours, daily and weekly working hours, rest intervals, overtime wages, leave with wages and the registration of the establishment within thirty days of commencement. The registration certificate must be displayed at the premises and the registers of employment and wages preserved for three years.', 'https://labour.tn.gov.in/', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_acts WHERE act_name = 'Tamil Nadu Shops and Establishments Act, 1947');

INSERT INTO compliance_acts (act_name, short_name, act_number, act_year, jurisdiction, state_name, ministry, department, enactment_date, effective_date, applicability_criteria, industry_applicability, employee_threshold, summary, official_source_url, status)
  SELECT 'Employees'' Compensation Act, 1923', 'EC Act', '8 of 1923', 1923, 'Central', NULL, 'Ministry of Labour and Employment', 'Office of the Labour Commissioner', '1923-03-05', '1923-07-01', 'Applies to every employer of persons employed in construction, railways, factories, mines, plantations and the other employments listed in the Schedules. Where the ESI Act applies to an employee, compensation under this Act is not payable for the same injury.', 'Construction, transport, mines, factories and other listed employments', 'All employers in listed employments', 'Requires the employer to pay compensation for injury by accident arising out of and in the course of employment — temporary or permanent disablement, or death — calculated on the wage slab notified by the Central Government, and to report fatal accidents within seven days.', 'https://labour.gov.in/acts/employees-compensation-act-1923', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_acts WHERE act_name = 'Employees'' Compensation Act, 1923');

INSERT INTO compliance_acts (act_name, short_name, act_number, act_year, jurisdiction, state_name, ministry, department, enactment_date, effective_date, applicability_criteria, industry_applicability, employee_threshold, summary, official_source_url, status)
  SELECT 'Industrial Disputes Act, 1947', 'ID Act', '14 of 1947', 1947, 'Central', NULL, 'Ministry of Labour and Employment', 'Office of the Labour Commissioner', '1947-03-11', '1947-04-01', 'Applies to all industrial establishments with one or more workmen. The special provisions on lay-off, retrenchment and closure (sections 25K, 25M, 25N and 25-O) apply to establishments employing one hundred or more workmen on an average per working day in the preceding twelve months.', 'All industrial establishments', 'All · special provisions at 100 or more', 'Governs lay-off, retrenchment, closure and transfer of undertakings, defines unfair labour practices, and sets out the machinery for settling industrial disputes through works committees, conciliation, labour courts and industrial tribunals. A Grievance Redressal Committee is mandatory at establishments with twenty or more workmen.', 'https://labour.gov.in/acts/industrial-disputes-act-1947', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_acts WHERE act_name = 'Industrial Disputes Act, 1947');


-- ───────────────────────── obligations (rules) ──────────────────────

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1), 'F-01', 'Factory licence and registration renewal', 'The occupier must hold a valid licence and registration certificate for the factory and renew it before the period stated on the licence lapses; the licence must be displayed at the premises.', 'Mandatory', 'Annual', NULL, 'Plant Head / Factory Manager', 'Under section 92 of the Act — imprisonment up to two years or fine up to ₹1,00,000, or both, with a further fine for continuing offence.', 'Factory licence, registration certificate, renewal receipt / challan.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1) AND rule_title = 'Factory licence and registration renewal');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1), 'F-02', 'Safety committee and safety officer', 'Factories employing 1,000 or more workers must constitute a safety committee and appoint a qualified safety officer; the committee must meet at least once a quarter and record its minutes.', 'Mandatory', 'Monthly', 5, 'Safety Officer', 'Section 92 — fine and, in hazardous process factories, imprisonment on repeated contravention.', 'Safety committee constitution order, appointment letter of the safety officer, quarterly meeting minutes.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1) AND rule_title = 'Safety committee and safety officer');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1), 'F-03', 'Testing of lifting machines, chains and ropes', 'Every lifting machine, chain, rope and lifting tackle must be thoroughly examined by a competent person at least once in twelve months, and the register of examinations maintained.', 'Mandatory', 'Annual', 15, 'Maintenance Engineer', 'Section 92 — general penalty for offences.', 'Competent person certificate (Form 8 register), examination report, register of lifting machines.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1) AND rule_title = 'Testing of lifting machines, chains and ropes');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1), 'F-04', 'Reporting of accidents and dangerous occurrences', 'Notice of any accident causing death or bodily injury resulting in absence from work for more than 48 hours, and of any dangerous occurrence, must be sent to the prescribed authority within the time limits in the state rules.', 'Mandatory', 'Event-based', NULL, 'Safety Officer', 'Section 92 read with the state Factory Rules — fine and imprisonment for failure to report a notifiable accident.', 'Notice of accident (Form 18 / state equivalent), acknowledgement from the Inspector of Factories, investigation report.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1) AND rule_title = 'Reporting of accidents and dangerous occurrences');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1), 'F-05', 'Pre-employment and periodic medical examination of workers in hazardous processes', 'Workers employed in hazardous processes must be medically examined before employment and periodically thereafter, with the health records preserved for the prescribed period and the worker informed of the findings.', 'Mandatory', 'Annual', NULL, 'Occupational Health Centre', 'Section 92 — general penalty; section 96A — additional liability of the occupier.', 'Occupational health centre records, medical examination schedule, worker health cards.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1) AND rule_title = 'Pre-employment and periodic medical examination of workers in hazardous processes');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952' LIMIT 1), 'EPF-01', 'Monthly provident fund contributions and ECR filing', 'Employer and employee contributions for each month must be deposited with the EPFO by the 15th of the following month, with the electronic challan-cum-return (ECR) filed for the same month.', 'Mandatory', 'Monthly', 15, 'Payroll Manager', 'Section 14B — damages up to the amount of arrears; section 7Q — 12% interest per annum on delayed deposit; prosecution under section 14.', 'Monthly challan, ECR acknowledgement, bank remittance proof.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952' LIMIT 1) AND rule_title = 'Monthly provident fund contributions and ECR filing');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952' LIMIT 1), 'EPF-02', 'Employee enrolment and UAN linkage', 'Every eligible employee must be enrolled and their Aadhaar linked to the Universal Account Number within one month of joining; KYC and nomination details must be updated on the EPFO portal.', 'Mandatory', 'Event-based', NULL, 'HR Manager', 'Section 14 — prosecution for failure to comply with the scheme.', 'UAN allotment proof, KYC/Nomination printout, employee enrolment register.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952' LIMIT 1) AND rule_title = 'Employee enrolment and UAN linkage');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952' LIMIT 1), 'EPF-03', 'Annual PF account reconciliation and UAN informatics check', 'Reconcile the payroll deductions, the ECR filed and the EPFO passbook balances for the financial year, and resolve discrepancies before the accounts are closed.', 'Recommended', 'Annual', NULL, 'Payroll Manager', '—', 'Reconciliation statement, passbook downloads, discrepancy resolution notes.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952' LIMIT 1) AND rule_title = 'Annual PF account reconciliation and UAN informatics check');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' State Insurance Act, 1948' LIMIT 1), 'ESI-01', 'Monthly ESI contribution and return of contributions', 'Contributions for the contribution period must be paid within 15 days of the last day of the month of payment of wages, and the return of contributions filed for the period.', 'Mandatory', 'Monthly', 15, 'Payroll Manager', 'Regulation 31 of the ESI (General) Regulations — damages; section 85 — prosecution with imprisonment up to two years for failure to pay contributions.', 'Payment challan, return of contributions acknowledgement, bank receipt.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' State Insurance Act, 1948' LIMIT 1) AND rule_title = 'Monthly ESI contribution and return of contributions');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' State Insurance Act, 1948' LIMIT 1), 'ESI-02', 'Employee registration, TIC and dependants’ records', 'Employees must be registered within ten days of joining, temporary identification certificates issued until the insurance number is allotted, and the family particulars of each insured person kept up to date.', 'Mandatory', 'Event-based', NULL, 'HR Manager', 'Section 85 — prosecution; employer liable for benefit paid during the period of default.', 'Employer code certificate, employee registration list, dependants register.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' State Insurance Act, 1948' LIMIT 1) AND rule_title = 'Employee registration, TIC and dependants’ records');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Contract Labour (Regulation and Abolition) Act, 1970' LIMIT 1), 'CL-01', 'Principal employer registration certificate', 'The principal employer must apply to the registering officer for a certificate of registration before engaging contract labour in the establishment and pay the prescribed fee.', 'Mandatory', 'One-time', NULL, 'HR Manager', 'Section 24 — imprisonment up to three months or fine up to ₹1,000, or both, with a continuing fine for subsisting failure.', 'Certificate of registration, application (Form I), fee challan, list of contractor details.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Contract Labour (Regulation and Abolition) Act, 1970' LIMIT 1) AND rule_title = 'Principal employer registration certificate');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Contract Labour (Regulation and Abolition) Act, 1970' LIMIT 1), 'CL-02', 'Contractor licence verification', 'No contractor may be engaged without a valid licence; the principal employer must verify the licence, keep a copy on file and ensure the licence remains in force for the duration of the work.', 'Mandatory', 'Event-based', NULL, 'Contract Cell', 'Section 23 — imprisonment up to three months or fine up to ₹1,000, or both, for employing contract labour without a licence.', 'Contractor licence copy, licence validity register, contractor-wise work order.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Contract Labour (Regulation and Abolition) Act, 1970' LIMIT 1) AND rule_title = 'Contractor licence verification');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Contract Labour (Regulation and Abolition) Act, 1970' LIMIT 1), 'CL-03', 'Register of contract workmen and wage payments', 'Maintain the register of workmen employed by each contractor, the muster roll, the register of wages and deductions, and the wage slips; wages must be paid in the presence of the authorised representative of the principal employer.', 'Mandatory', 'Monthly', 7, 'Contract Cell', 'Section 23 read with Rule 78 of the Central Rules — fine.', 'Register of workmen, muster roll, wage registers, bank statements, wage slip acknowledgements.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Contract Labour (Regulation and Abolition) Act, 1970' LIMIT 1) AND rule_title = 'Register of contract workmen and wage payments');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Payment of Gratuity Act, 1972' LIMIT 1), 'GR-01', 'Gratuity payment within thirty days of it falling due', 'Determine and pay gratuity within thirty days from the date it becomes payable, whether or not the employee applies for it; if not paid in time, pay simple interest at the notified rate.', 'Mandatory', 'Event-based', NULL, 'Payroll Manager', 'Section 9 — imprisonment up to two years, or fine up to ₹2,00,000, or both, for non-payment; section 8 — recovery as arrears of land revenue.', 'TDS-free gratuity calculation sheet, payment advice, bank proof, employee acknowledgement.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Payment of Gratuity Act, 1972' LIMIT 1) AND rule_title = 'Gratuity payment within thirty days of it falling due');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Payment of Gratuity Act, 1972' LIMIT 1), 'GR-02', 'Nomination and display of the abstract', 'Obtain a nomination from each employee and display the abstract of the Act and the rules at a conspicuous place in the establishment, in English and the language understood by the majority of employees.', 'Mandatory', 'One-time', NULL, 'HR Manager', '—', 'Signed nominations, photograph of the displayed abstract.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Payment of Gratuity Act, 1972' LIMIT 1) AND rule_title = 'Nomination and display of the abstract');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Maternity Benefit Act, 1961' LIMIT 1), 'MB-01', 'Maternity leave, bonus and nursing breaks', 'Grant twenty-six weeks'' paid leave for the first two children and twelve weeks for subsequent children, pay the medical bonus, provide nursing breaks until the child is fifteen months old, and allow the leave to start up to eight weeks before the expected date of delivery.', 'Mandatory', 'Event-based', NULL, 'HR Manager', 'Section 21 — imprisonment up to one year, or fine up to ₹5,000, or both.', 'Application for maternity benefit, medical certificate, wage payment records for the leave period.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Maternity Benefit Act, 1961' LIMIT 1) AND rule_title = 'Maternity leave, bonus and nursing breaks');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Maternity Benefit Act, 1961' LIMIT 1), 'MB-02', 'Crèche facility and notice', 'Establishments with fifty or more employees must provide a crèche facility, allow the woman four visits a day to it, and inform every woman at the time of appointment and thereafter of the maternity benefits available.', 'Mandatory', 'Monthly', 1, 'HR Manager', 'Section 21 — fine; Rule 5(3) of the Maternity Benefit (Mines and Circus) Rules for the intimation requirement.', 'Crèche facility details, appointment intimation, record of crèche visits.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Maternity Benefit Act, 1961' LIMIT 1) AND rule_title = 'Crèche facility and notice');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Tamil Nadu Shops and Establishments Act, 1947' LIMIT 1), 'TNSE-01', 'Registration of the establishment and display of the certificate', 'Register the establishment in Form A within thirty days of commencement of business with the Inspector of the area, renew the registration as prescribed and display the certificate of registration at the premises.', 'Mandatory', 'One-time', NULL, 'Establishment Head', 'Section 38 — fine not less than ₹500 but up to ₹5,000 for a first offence, and imprisonment on repeat contraventions.', 'Form A application, certificate of registration, fee receipt, photograph of the displayed certificate.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Tamil Nadu Shops and Establishments Act, 1947' LIMIT 1) AND rule_title = 'Registration of the establishment and display of the certificate');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Tamil Nadu Shops and Establishments Act, 1947' LIMIT 1), 'TNSE-02', 'Registers of employment, wages and leave', 'Maintain the register of employment (Form L / register of sales), the wage register, the leave register and the register of attendance in the prescribed form and preserve them for three years.', 'Mandatory', 'Monthly', 10, 'HR Manager', 'Section 17 read with section 38 — fine.', 'Register of employment, wage register, leave register, attendance records.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Tamil Nadu Shops and Establishments Act, 1947' LIMIT 1) AND rule_title = 'Registers of employment, wages and leave');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Tamil Nadu Shops and Establishments Act, 1947' LIMIT 1), 'TNSE-03', 'Weekly holiday and daily working-hour compliance', 'Allow one whole day for rest in every week, keep daily working hours in the ordinary course within nine hours and forty-eight hours in a week, provide the prescribed interval after five hours of continuous work and pay overtime at twice the ordinary rate.', 'Mandatory', 'Weekly', NULL, 'Establishment Head', 'Section 38 — fine per contravention.', 'Attendance register, overtime register, wage register showing overtime paid.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Tamil Nadu Shops and Establishments Act, 1947' LIMIT 1) AND rule_title = 'Weekly holiday and daily working-hour compliance');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Compensation Act, 1923' LIMIT 1), 'EC-01', 'Reporting a fatal accident within seven days', 'Send notice of any accident causing death or serious bodily injury to the Commissioner for Employees'' Compensation within seven days of its occurrence, and prefer a claim on behalf of the dependants.', 'Mandatory', 'Event-based', NULL, 'Safety Officer', 'Section 18A — penalty on the employer for failure to submit the required report.', 'Notice of accident to the Commissioner, accident register, post-mortem / medical report, claim papers.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Compensation Act, 1923' LIMIT 1) AND rule_title = 'Reporting a fatal accident within seven days');

INSERT INTO compliance_rules (act_id, rule_number, rule_title, rule_text, compliance_type, frequency, due_day_of_month, responsible_role, penalty_details, evidence_required, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Industrial Disputes Act, 1947' LIMIT 1), 'ID-01', 'Grievance Redressal Committee at establishments with 20 or more workmen', 'Constitute a Grievance Redressal Committee with the prescribed composition for establishments with twenty or more workmen, and complete the decision-making process within forty-five days of receiving a grievance.', 'Mandatory', 'One-time', NULL, 'HR Manager', 'Section 25U — fine for contravention of the provisions relating to lay-off, retrenchment and closure read with the Grievance Redressal machinery.', 'Committee constitution order, grievance register, minutes of the committee meetings.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_rules WHERE act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Industrial Disputes Act, 1947' LIMIT 1) AND rule_title = 'Grievance Redressal Committee at establishments with 20 or more workmen');


-- ────────────────────────── instruments (regulations) ───────────────

INSERT INTO compliance_regulations (act_id, rule_id, regulation_name, regulation_number, issuing_authority, issue_date, effective_date, scope, obligations, reporting_authority, reporting_frequency, penalty_provision, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1), (SELECT id FROM compliance_rules WHERE rule_number = 'F-01' AND act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Factories Act, 1948' LIMIT 1) LIMIT 1), 'Tamil Nadu Factory Rules, 1950', 'G.O. Ms. No. 2229', 'Government of Tamil Nadu, Labour Department', '1950-06-01', '1950-06-01', 'Applies to every factory in Tamil Nadu registered under the Factories Act, 1948, and to the occupier, manager and workers of those factories.', 'Prescribes the form of application for registration and licence (Form 1 and 2), the layout approval process, safety and welfare provisions specific to the state, the registers and forms to be maintained, and the fees payable for licence and renewal.', 'Inspector of Factories, Tamil Nadu', 'Annual licence renewal', 'Rule 118 read with section 92 of the Act for contravention of the rules.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_regulations WHERE regulation_name = 'Tamil Nadu Factory Rules, 1950');

INSERT INTO compliance_regulations (act_id, rule_id, regulation_name, regulation_number, issuing_authority, issue_date, effective_date, scope, obligations, reporting_authority, reporting_frequency, penalty_provision, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952' LIMIT 1), (SELECT id FROM compliance_rules WHERE rule_number = 'EPF-01' AND act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952' LIMIT 1) LIMIT 1), 'Employees'' Provident Funds Scheme, 1952', 'G.S.R. 1509', 'Employees'' Provident Fund Organisation', '1952-09-02', '1952-11-01', 'Applies to every establishment covered by the Act and to every employee eligible for membership of the Fund.', 'Sets out the rate of contributions (12% of basic wages and dearness allowance by employee and employer, with 8.33% of the employer share diverted to the Pension Fund), the maintenance of the provident fund account, withdrawal and advance conditions, and the monthly ECR compliance process.', 'Regional Provident Fund Commissioner', 'Monthly by the 15th', 'Section 14B for damages on delayed remittance, section 7Q for interest, and section 14 for prosecution.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_regulations WHERE regulation_name = 'Employees'' Provident Funds Scheme, 1952');

INSERT INTO compliance_regulations (act_id, rule_id, regulation_name, regulation_number, issuing_authority, issue_date, effective_date, scope, obligations, reporting_authority, reporting_frequency, penalty_provision, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' State Insurance Act, 1948' LIMIT 1), (SELECT id FROM compliance_rules WHERE rule_number = 'ESI-01' AND act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' State Insurance Act, 1948' LIMIT 1) LIMIT 1), 'Employees'' State Insurance (General) Regulations, 1950', 'G.S.R. 96', 'Employees'' State Insurance Corporation', '1950-06-17', '1952-02-24', 'Applies to every covered establishment, insured person and employer within implemented areas.', 'Prescribes the employer code application, registration of employees and issue of the temporary identification certificate, the contribution period and benefit period, payment of contributions within 15 days, maintenance of the register of employees, and the return of contributions.', 'Regional Office, ESI Corporation', 'Monthly with the return of contributions', 'Regulation 31 for damages on delayed payment and section 85 of the Act for prosecution.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_regulations WHERE regulation_name = 'Employees'' State Insurance (General) Regulations, 1950');

INSERT INTO compliance_regulations (act_id, rule_id, regulation_name, regulation_number, issuing_authority, issue_date, effective_date, scope, obligations, reporting_authority, reporting_frequency, penalty_provision, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Contract Labour (Regulation and Abolition) Act, 1970' LIMIT 1), (SELECT id FROM compliance_rules WHERE rule_number = 'CL-03' AND act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Contract Labour (Regulation and Abolition) Act, 1970' LIMIT 1) LIMIT 1), 'Contract Labour (Regulation and Abolition) Central Rules, 1971', 'G.S.R. 191', 'Ministry of Labour and Employment', '1971-02-10', '1971-02-10', 'Applies to every principal employer and contractor covered by the Act across central sphere establishments, and to the records they must maintain.', 'Prescribes the registers of contractors, workmen, wages and deductions, overtime, and the forms for the certificate of registration and licence, together with the welfare amenities — canteen, rest room, drinking water, latrines and first aid — that must be provided where the prescribed number of contract workmen is engaged.', 'Office of the Chief Labour Commissioner (Central)', 'On demand / annual return', 'Rule 78 read with sections 23 and 24 of the Act.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_regulations WHERE regulation_name = 'Contract Labour (Regulation and Abolition) Central Rules, 1971');

INSERT INTO compliance_regulations (act_id, rule_id, regulation_name, regulation_number, issuing_authority, issue_date, effective_date, scope, obligations, reporting_authority, reporting_frequency, penalty_provision, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' State Insurance Act, 1948' LIMIT 1), (SELECT id FROM compliance_rules WHERE rule_number = 'ESI-02' AND act_id = (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' State Insurance Act, 1948' LIMIT 1) LIMIT 1), 'Employees'' State Insurance (Central) Amendment Rules, 2016 — wage ceiling raised', 'G.S.R. 1211(E)', 'Ministry of Labour and Employment', '2016-12-28', '2017-01-01', 'Applies to all covered establishments; it raised the wage limit for coverage of employees from ₹15,000 to ₹21,000 per month.', 'Employers must add employees drawing wages up to the revised ceiling to the ESI rolls, and continue the coverage of employees already registered whose wages remain within the ceiling.', 'Regional Office, ESI Corporation', 'Monthly with the return of contributions', 'Section 85 of the Act where contributions are not paid on the enlarged coverage.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_regulations WHERE regulation_name = 'Employees'' State Insurance (Central) Amendment Rules, 2016 — wage ceiling raised');

INSERT INTO compliance_regulations (act_id, rule_id, regulation_name, regulation_number, issuing_authority, issue_date, effective_date, scope, obligations, reporting_authority, reporting_frequency, penalty_provision, status)
  SELECT (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952' LIMIT 1), NULL, 'Employees’ Pension Scheme, 1995', 'G.S.R. 390(E)', 'Employees'' Provident Fund Organisation', '1995-11-16', '1995-11-16', 'Applies to every member of the Employees’ Provident Fund who is entitled to pension under the scheme.', 'Provides for pension on superannuation, retirement, permanent total disablement, widow/widower pension, children pension and orphan pension, and prescribes the minimum ten years'' eligible service for pension and the computation of pensionable salary.', 'Regional Provident Fund Commissioner', 'Monthly through the ECR', 'Section 14B and 7Q of the Act for short or delayed remittance of the pension fund share.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_regulations WHERE regulation_name = 'Employees’ Pension Scheme, 1995');


-- ───────────────────────── gazette notifications ────────────────────

INSERT INTO compliance_notifications (notification_number, title, notification_date, issuing_authority, act_id, gazette_reference, subject, body, effective_date, applicability, action_required, status)
  SELECT 'G.S.R. 1211(E)', 'ESI wage ceiling for coverage raised from ₹15,000 to ₹21,000 per month', '2016-12-28', 'Ministry of Labour and Employment', (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' State Insurance Act, 1948' LIMIT 1), 'The Gazette of India, Extraordinary, Part II, Section 3(i)', 'Amendment to Rule 50 of the Employees’ State Insurance (Central) Rules, 1950 revising the wage limit for coverage of employees.', 'The Central Government raised the wage limit for coverage of an employee under the ESI Act from ₹15,000 to ₹21,000 per month with effect from 1 January 2017. Establishments must enrol employees whose wages fall within the revised ceiling and continue to cover those already registered.', '2017-01-01', 'Every establishment covered by the ESI Act and every employee whose wages do not exceed the revised ceiling.', 'Update the employee master, add newly covered employees to the ESI rolls and recalculate the monthly contribution before filing the next return.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_notifications WHERE notification_number = 'G.S.R. 1211(E)');

INSERT INTO compliance_notifications (notification_number, title, notification_date, issuing_authority, act_id, gazette_reference, subject, body, effective_date, applicability, action_required, status)
  SELECT 'G.S.R. 609(E)', 'EPF wage ceiling for compulsory coverage raised from ₹6,500 to ₹15,000 per month', '2014-08-22', 'Ministry of Labour and Employment', (SELECT id FROM compliance_acts WHERE act_name = 'Employees'' Provident Funds and Miscellaneous Provisions Act, 1952' LIMIT 1), 'The Gazette of India, Extraordinary, Part II, Section 3(i)', 'Amendment to paragraph 2 of the Employees’ Provident Funds Scheme, 1952 raising the wage ceiling for coverage.', 'The wage ceiling for compulsory coverage under the Employees’ Provident Funds Scheme was revised to ₹15,000 per month. Employees drawing wages above the ceiling at the time of joining may become members by joint option of employer and employee; those already covered remain members.', '2014-09-01', 'Every establishment covered by the EPF Act and employees drawing wages up to ₹15,000 per month.', 'Review the employee master for newly covered members, obtain nominations and enrol them with the EPFO.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_notifications WHERE notification_number = 'G.S.R. 609(E)');

INSERT INTO compliance_notifications (notification_number, title, notification_date, issuing_authority, act_id, gazette_reference, subject, body, effective_date, applicability, action_required, status)
  SELECT 'Act No. 6 of 2017', 'Maternity Benefit (Amendment) Act, 2017 — 26 weeks’ paid leave and crèche facility', '2017-03-27', 'Ministry of Law and Justice (Legislative Department)', (SELECT id FROM compliance_acts WHERE act_name = 'Maternity Benefit Act, 1961' LIMIT 1), 'The Gazette of India, Extraordinary, Part II, Section 1', 'Amendment to sections 5, 11A and 12 of the Maternity Benefit Act, 1961.', 'Paid maternity leave for the first two children was extended to twenty-six weeks (with not more than eight weeks before the expected date of delivery), leave for the third child onwards remains twelve weeks, an establishment with fifty or more employees must provide a crèche, and an employer may permit work from home where the nature of work permits.', '2017-04-01', 'Every establishment covered by the Maternity Benefit Act, 1961.', 'Revise the leave policy, set up or contract a crèche facility where fifty or more employees are employed, and inform every woman employee of the enhanced benefits at the time of appointment.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_notifications WHERE notification_number = 'Act No. 6 of 2017');

INSERT INTO compliance_notifications (notification_number, title, notification_date, issuing_authority, act_id, gazette_reference, subject, body, effective_date, applicability, action_required, status)
  SELECT 'G.O. Ms. No. 76', 'Tamil Nadu — extension of the TNSE registration portal and e-renewal requirement', '2020-06-15', 'Labour and Employment Department, Government of Tamil Nadu', (SELECT id FROM compliance_acts WHERE act_name = 'Tamil Nadu Shops and Establishments Act, 1947' LIMIT 1), 'Tamil Nadu Government Gazette, Part II, Section 2', 'Directions for online registration and renewal of establishments under the Tamil Nadu Shops and Establishments Act, 1947.', 'Establishments in Tamil Nadu must register online through the Labour Department portal, obtain the e-registration certificate and renew through the same portal. The certificate must be displayed at the premises.', '2020-07-01', 'Every shop, commercial establishment, hotel and restaurant in Tamil Nadu.', 'Migrate any paper registration to the portal, print and display the e-certificate and note the renewal date for tracking.', 'active' WHERE NOT EXISTS (SELECT 1 FROM compliance_notifications WHERE notification_number = 'G.O. Ms. No. 76');
